  "meaning_id": "kompatibilitas, kemampuan dua sistem atau komponen bekerja bersama tanpa masalah",
  "meaning_en": "compatibility, interoperability",
  "jlpt": "n2",
  "pos": "noun",
  "common": true,
  "related_grammar": [],
  "formalitas": 3,
